#ifdef NDEBUG
#error "Assertions must remain enabled."
#endif
#include <cassert>
#include <iostream>
enum class Phase { Reading, Preparing, Ready, Failed };
struct Loader {
    Phase phase=Phase::Reading;
    int loaded=0;
    bool readUnit(){
        if(phase!=Phase::Reading)return false;
        if(++loaded==4)phase=Phase::Preparing;
        return true;
    }
    bool prepared(){
        if(phase!=Phase::Preparing)return false;
        phase=Phase::Ready;return true;
    }
    void fail(){if(phase!=Phase::Ready)phase=Phase::Failed;}
    bool canPlay()const{return phase==Phase::Ready;}
};
int main(){
    Loader x;assert(!x.prepared());assert(!x.canPlay());
    for(int i=0;i<4;++i){assert(x.readUnit());assert(!x.canPlay());}
    assert(x.loaded==4 && x.phase==Phase::Preparing);
    assert(!x.readUnit());assert(x.prepared());assert(x.canPlay());
    assert(!x.prepared());
    Loader y;y.readUnit();y.fail();
    assert(!y.readUnit() && !y.prepared() && !y.canPlay());
    std::cout<<"loading state tests passed\n";
}
